from rdkit import Chem
strings = [
'[O][=C][O][C][Branch1][Branch1][C][C][C][Cl][C][N][Ring1][=Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1]',
'[C][=C][N][=C][Branch1][=Branch2][N][C][C][N][C][C][Ring1][=Branch1][N][=C][Ring1][N]',
'[C][C][C][C][O]','[Cl]','[Cl]','[O][=C][Branch1][C][O-1][O-1]','[I-1]','[K+1]','[K+1]','[K+1]']
try:
 import selfies as sf
 print('SELFIES available')
 for s in strings:
  try:
   smi=sf.decoder(s)
   m=Chem.MolFromSmiles(smi)
   print(s, '\n ->', smi, 'valid', bool(m))
   if m: print(Chem.MolToSmiles(m))
  except Exception as e: print('ERR',e)
except Exception as e:
 print('SELFIES unavailable',e)
 print('RDKit only')
 for s in strings:
  m=Chem.MolFromSmiles(s)
  print(s, bool(m), Chem.MolToSmiles(m) if m else '')
